import { View, Text, Button } from 'react-native';

export default function App() {
  let count = 0;

  return (
    <View>
      <Text>{count}</Text>
      <Button
        title="Somar"
        onPress={() => {
          count = count + 1;
        }}
      />
    </View>
  );
}

questions.solution:
import { useState } from 'react';
import { View, Text, Button } from 'react-native';

export default function App() {
  const [count, setCount] = useState(0);

  return (
    <View>
      <Text>{count}</Text>
      <Button title="Somar" onPress={() => setCount(count + 1)} />
    </View>
  );
}

